const input=$json.body??$json;
const dispatch=input.dispatch??{};
const provider=input.provider??{};
const delivery=String(input.delivery_status??input.receipt_status??dispatch.delivery_status??"").toLowerCase();
const inbound=Boolean(input.inbound_message||input.seller_response||input.message_direction==="inbound");
const channel=String(dispatch.channel||input.channel||"").toLowerCase();
const recipient=String(dispatch.recipient||input.recipient||"").trim();
const dispatchId=String(dispatch.dispatch_id||input.dispatch_id||"").trim();
const dnc=Boolean(input.dnc||input.do_not_contact);
let status="receipt_pending",state="pending",nextWorkflow="WF-289",human=false,reason="delivery receipt is pending";
if(dnc){status="blocked_dnc";state="blocked";nextWorkflow="WF-126";human=true;reason="seller is marked do-not-contact";}
else if(!dispatchId||!recipient||!["sms","email"].includes(channel)){status="dispatch_identity_invalid";state="blocked";nextWorkflow="WF-126";human=true;reason="dispatch identity, recipient, and channel are required";}
else if(inbound||delivery==="response_received"||delivery==="replied"){
  status="seller_response_received";state="response_received";nextWorkflow="WF-296";human=false;reason="seller response received and ready for classification";
}
else if(["delivered","delivery_confirmed","sent"].includes(delivery)){
  status="delivered_awaiting_response";state="delivered";nextWorkflow="WF-296";human=false;reason="message delivered; awaiting seller response";
}
else if(["failed","undelivered","bounced","rejected"].includes(delivery)){
  status="delivery_failed";state="failed";nextWorkflow="WF-289";human=true;reason="provider reported delivery failure";
}
else if(["timeout","expired"].includes(delivery)){
  status="seller_response_timeout";state="timeout";nextWorkflow="WF-290";human=false;reason="seller response window expired";
}
const idempotencyKey=input.idempotency_key||`wf-295:${dispatchId||"unknown"}:${input.provider_event_id||input.version||1}`;
return [{json:{...input,workflow:"WF-295",workflow_name:"Seller Dispatch → Delivery Receipt & Response Controller",status,delivery_state:{state,delivery_status:delivery||null,dispatch_id:dispatchId,channel,recipient,provider_event_id:provider.event_id||input.provider_event_id||null,reason},next_workflow:nextWorkflow,human_review_required:human,audit:{event_type:"seller_dispatch_delivery_receipt_response",idempotency_key:idempotencyKey}}}];
